package com.yihe.framework.ehr;

import java.util.*;
import org.springframework.stereotype.Service;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;

/** Checks provenance and extraction quality; never infers a clinical diagnosis. */
@Service
public class ArchiveQualityService {
 static final String RULE="archive-quality-v7-context";
 final EhrRepository db;final EhrService ehr;
 public ArchiveQualityService(EhrRepository db,EhrService ehr){this.db=db;this.ehr=ehr;}
 static Map<String,Object> issue(String key,String category,String severity,String item,String message){return map("key",key,"category",category,"severity",severity,"itemId",item,"message",message);}
 @SuppressWarnings("unchecked") public Map<String,Object> inspect(EhrActor a,Map<String,Object> h){
  String id=str(h.get("report_id"));int rev=num(h.get("revision"));List<Map<String,Object>> issues=new ArrayList<>();String etag=hex(digest(bytes(ehr.encode(ehr.snapshot(id,rev))))),stamp=originalStamp(a,id,rev);Set<String> modelApproved=modelApproved(id,rev,etag,stamp);
  List<Map<String,Object>> files=db.all("SELECT s.source_file_id id,s.page_count pages FROM a_report_revision_sources r JOIN a_report_sources s ON s.source_file_id=r.source_file_id WHERE r.report_id=? AND r.revision=?",id,rev);
  for(Map<String,Object> f:files)try{ehr.download(a,str(f.get("id")));}catch(EhrException missing){issues.add(issue("original_unavailable:"+f.get("id"),"original","blocking",null,"原件存储不可用，等待恢复后自动入档"));}
  if(files.isEmpty())issues.add(issue("original_missing","original","blocking",null,"报告原件未关联，暂不能自动入档"));
  if(h.get("exam_date_verified")!=null&&java.time.LocalDate.parse(str(h.get("exam_date_verified"))).isAfter(java.time.LocalDate.now(java.time.ZoneOffset.UTC)))issues.add(issue("future_date","metadata","blocking",null,"体检日期在未来，请核对原件"));
  if(h.get("exam_date_verified")==null)issues.add(issue("exam_date","metadata","blocking",null,"体检日期缺失或无法确定，请核对原件"));
  if(str(h.get("institution_raw")).trim().isEmpty())issues.add(issue("institution","metadata","field",null,"体检机构未明确，原件先入档，机构待核验"));
  if(ehr.reportKindUncertain(id,rev))issues.add(issue("report_kind","classification","blocking",null,"报告类型未确定，需确认是该职工个人体检报告"));
  long duplicates=db.count("SELECT COUNT(*) FROM a_report_archive_entries x JOIN a_report_series s ON s.report_id=x.report_id AND s.current_revision=x.revision JOIN a_health_reports old ON old.report_id=x.report_id AND old.revision=x.revision WHERE x.scope_code=? AND x.data_mode=? AND x.record_id=? AND x.report_id<>? AND x.archive_status IN ('archived','partial') AND COALESCE(old.exam_date_verified,old.exam_date_raw)=COALESCE(?,?) AND old.institution_raw=?",a.scope,a.mode,h.get("record_id"),id,h.get("exam_date_verified"),h.get("exam_date_raw"),h.get("institution_raw"));
  // Also detect medically published reports created before administrative archiving existed.
  duplicates+=db.count("SELECT COUNT(*) FROM a_report_publications p JOIN a_report_series s ON s.report_id=p.report_id AND s.current_revision=p.revision JOIN a_health_reports old ON old.report_id=p.report_id AND old.revision=p.revision WHERE p.scope_code=? AND p.data_mode=? AND p.record_id=? AND p.report_id<>? AND COALESCE(old.exam_date_verified,old.exam_date_raw)=COALESCE(?,?) AND old.institution_raw=?",a.scope,a.mode,h.get("record_id"),id,h.get("exam_date_verified"),h.get("exam_date_raw"),h.get("institution_raw"));
  if(duplicates>0)issues.add(issue("duplicate_report","duplicate","blocking",null,"发现同一职工、日期和机构的已入档报告，暂不重复入档，请核验是否同一报告"));
  Map<String,String> nativePages=new HashMap<>(),nativeRawPages=new HashMap<>();for(Map<String,Object> f:files)try{java.nio.file.Path path=ehr.download(a,str(f.get("id")));Map<String,Object> stored=db.one("SELECT sha256 FROM a_report_sources WHERE source_file_id=?",f.get("id"));if(!Arrays.equals((byte[])stored.get("sha256"),digest(java.nio.file.Files.readAllBytes(path)))){issues.add(issue("hash:"+f.get("id"),"original","blocking",null,"原件摘要与上传记录不一致，请恢复正确原件"));continue;}com.itextpdf.text.pdf.PdfReader doc=new com.itextpdf.text.pdf.PdfReader(path.toString());try{if(doc.getNumberOfPages()!=num(f.get("pages"))){issues.add(issue("pages:"+f.get("id"),"original","blocking",null,"原件页数与上传记录不一致"));continue;}for(int n=1;n<=doc.getNumberOfPages();n++){String rawText=com.itextpdf.text.pdf.parser.PdfTextExtractor.getTextFromPage(doc,n),text=ReportMatchingService.norm(rawText);if(!text.isEmpty()){nativePages.put(f.get("id")+":"+n,text);nativeRawPages.put(f.get("id")+":"+n,rawText);}}}finally{doc.close();}}catch(Exception unavailable){/* Images and scanned PDFs use the evidence/confidence path below. */}
  Map<String,Map<String,Object>> evidence=new HashMap<>();for(Map<String,Object> e:db.all("SELECT * FROM a_report_evidence WHERE report_id=? AND revision=?",id,rev))evidence.put(str(e.get("evidence_id")),e);
  int pageCount=0,coveredPages=0;for(Map<String,Object> f:files){int pages=num(f.get("pages"));pageCount+=pages;Set<Integer> covered=new HashSet<>();for(int n=1;n<=pages;n++)if(nativePages.containsKey(f.get("id")+":"+n))covered.add(n);for(Map<String,Object> e:evidence.values())if(f.get("id").equals(e.get("source_file_id"))&&!str(e.get("raw_fragment")).trim().isEmpty()&&num(e.get("page_number"))>=1&&num(e.get("page_number"))<=pages)covered.add(num(e.get("page_number")));coveredPages+=covered.size();}
  if(coveredPages<pageCount)issues.add(issue("page_coverage","pages","field",null,"部分原件页没有可追溯提取内容（"+coveredPages+"/"+pageCount+"页）；保留完整原件，缺页内容待核验"));
  List<Map<String,Object>> items=db.all("SELECT * FROM a_health_items WHERE report_id=? AND revision=? ORDER BY ordinal",id,rev);List<String> trusted=new ArrayList<>(),uncertain=new ArrayList<>(),excerpts=new ArrayList<>(),notReported=new ArrayList<>();Map<String,Set<String>> observations=new HashMap<>();
  for(Map<String,Object> item:items){Map<String,Object> source=evidence.get(str(item.get("primary_evidence_id")));String location=source==null?"":str(source.get("source_file_id"))+":"+str(source.get("page_number"));observations.computeIfAbsent(observationKey(item,location),k->new HashSet<>()).add(ReportMatchingService.norm(item.get("result_raw"))+"|"+ReportMatchingService.norm(item.get("unit_raw")));}
  for(Map<String,Object> item:items){String itemId=str(item.get("item_id")),name=str(item.get("original_field_name")),value=str(item.get("result_raw")),reason="";Map<String,Object> e=evidence.get(str(item.get("primary_evidence_id")));String sourceMatch=evidenceMatch(item,evidence);
   if(value.trim().isEmpty()&&blankOptionalResult(name,e,nativeRawPages)){notReported.add(itemId);continue;}
   if(name.trim().isEmpty()||value.trim().isEmpty())reason="检查项目名或原始结果缺失";
   else if(e==null||str(e.get("raw_fragment")).trim().isEmpty()||!files.stream().anyMatch(f->f.get("id").equals(e.get("source_file_id"))&&num(e.get("page_number"))>0&&num(e.get("page_number"))<=num(f.get("pages"))))reason="原件出处或页码不可追溯";
   else if(!modelApproved.contains(itemId)&&"different".equals(sourceMatch))reason="结果与现存证据文字存在内容差异，请核对原件";
   else if(!modelApproved.contains(itemId)&&observations.get(observationKey(item,str(e.get("source_file_id"))+":"+str(e.get("page_number")))).size()>1&&!separateGenericObservation(item,e))reason="同一页同名检查项目存在不同原值，待核验时间或项目口径";
   if("rejected".equals(item.get("review_status")))reason="该指标已被人工标记退回";
   if(reason.isEmpty()){trusted.add(itemId);if("excerpt".equals(sourceMatch))excerpts.add(itemId);}else{uncertain.add(itemId);issues.add(issue("item:"+itemId,"field","field",itemId,name+"："+reason));}

  }
  issues.addAll(medicalAlerts(id,rev));
  if(items.isEmpty())issues.add(issue("items_missing","field","field",null,"尚无结构化体检指标，原件先入档，等待识别或补录"));
  if(db.count("SELECT COUNT(*) FROM a_health_conclusions WHERE report_id=? AND revision=? AND completeness='complete' AND TRIM(COALESCE(original_text,''))<>''",id,rev)==0&&!sourceCompleteConclusion(id,rev,evidence,nativeRawPages))issues.add(issue("conclusion","conclusion","field",null,"完整体检结论待核验；不阻塞原件和可信指标入档"));
  boolean blocked=issues.stream().anyMatch(i->"blocking".equals(i.get("severity")));boolean partial=issues.stream().anyMatch(i->"field".equals(i.get("severity")));
  return map("rule",RULE,"inputEtag",etag,"originalStamp",stamp,"verificationDigest",verificationDigest(id,rev,etag,stamp),"modelCrosscheckedItems",modelApproved.size(),"excerptItemIds",excerpts,"excerptItems",excerpts.size(),"blocked",blocked,"qualityStatus",blocked?"blocked":partial?"partial":"passed","archiveStatus",blocked?"pending":partial?"partial":"archived","issues",issues,"trustedItemIds",trusted,"notReportedItemIds",notReported,"notReportedItems",notReported.size(),"uncertainItemIds",uncertain,"totalItems",items.size(),"trustedItems",trusted.size(),"totalPages",pageCount,"coveredPages",coveredPages,"pageCoverage",pageCount==0?0:(100*coveredPages/pageCount),"nativeTextPages",nativePages.size(),"medicalReviewStatus","pending","medicalReviewRequired",true);
 }
 /** An OCR evidence quote may be an excerpt. Preserve it as such; do not claim a full-text verification. */
 @SuppressWarnings("unchecked") String evidenceMatch(Map<String,Object> item,Map<String,Map<String,Object>> evidence){String value=str(item.get("result_raw"));List<String> quotes=new ArrayList<>();Set<String> seen=new HashSet<>();Object refs=ehr.decode(item.get("evidence_ids"));List<Object> ids=new ArrayList<>();ids.add(item.get("primary_evidence_id"));if(refs instanceof List)ids.addAll((List<?>)refs);for(Object ref:ids){Map<String,Object> e=evidence.get(str(ref));if(e!=null&&seen.add(str(ref))&&!str(e.get("raw_fragment")).trim().isEmpty())quotes.add(str(e.get("raw_fragment")));}return compareQuotes(value,quotes);}
 static String paragraph(Object text){return java.text.Normalizer.normalize(str(text),java.text.Normalizer.Form.NFKC).replaceAll("[\\s\\u00a0\\u3000\\u200b\\ufeff]+","").replaceAll("[，,。;；:：!?！？、‘’“”\"（）()]","").replaceAll("(?<![0-9])\\.|\\.(?![0-9])","");}
 static String compareQuotes(String value,List<String> quotes){for(String quote:quotes)if(literalResult(quote,value))return "matched";boolean narrative=value.matches("(?s).*[\\u3400-\\u9fff].*");if(!narrative)return "different";String full=paragraph(value),joined=paragraph(String.join("",quotes));if(!full.isEmpty()&&joined.contains(full))return "matched";for(String quote:quotes){String part=paragraph(quote);if(!full.isEmpty()&&part.contains(full))return "matched";long chinese=part.chars().filter(c->c>=0x3400&&c<=0x9fff).count();// A complete opening clause is a valid excerpt even when an organ finding is only 6-9 characters.
   // Do not accept an arbitrary short prefix or claim the unseen remainder has been verified.
   String openingClause=paragraph(value.split("[，,。;；\\n\\r]",2)[0]);boolean completeOpeningClause=chinese>=6&&part.equals(openingClause);
   if((part.length()>=10&&chinese>=6||completeOpeningClause)&&full.length()>part.length()&&full.startsWith(part))return "excerpt";}return "different";}
 @SuppressWarnings("unchecked") Set<String> modelApproved(String report,int revision,String etag,String stamp){Map<String,Object> check=db.one("SELECT approved_item_ids FROM a_archive_original_checks WHERE report_id=? AND revision=? AND input_etag=? AND original_stamp=? AND check_status IN ('queued','running','completed')",report,revision,etag,stamp);return check==null?Collections.emptySet():new HashSet<>((List<String>)ehr.decode(check.get("approved_item_ids")));}
 String verificationDigest(String report,int revision,String etag,String stamp){List<String> ids=new ArrayList<>(modelApproved(report,revision,etag,stamp));Collections.sort(ids);return hex(digest(bytes(ehr.encode(ids))));}
 String originalStamp(EhrActor a,String report,int revision){try{List<String> stamps=new ArrayList<>();for(Map<String,Object> f:db.all("SELECT s.source_file_id id,s.sha256 FROM a_report_revision_sources r JOIN a_report_sources s ON s.source_file_id=r.source_file_id WHERE r.report_id=? AND r.revision=? ORDER BY s.source_file_id",report,revision)){java.nio.file.Path file=ehr.download(a,str(f.get("id")));stamps.add(f.get("id")+":"+java.nio.file.Files.size(file)+":"+java.nio.file.Files.getLastModifiedTime(file).toMillis()+":"+hex((byte[])f.get("sha256")));}return hex(digest(bytes(ehr.encode(stamps))));}catch(Exception error){return "unavailable";}}
 static String spaced(Object value){return java.text.Normalizer.normalize(str(value),java.text.Normalizer.Form.NFKC).replaceAll("[\\s\\u00a0\\u3000\\u200b\\ufeff]+"," ").trim().toLowerCase(Locale.ROOT);}
 static boolean literalResult(Object fragment,String raw){String value=spaced(raw);if(value.isEmpty())return false;boolean numeric=Character.isDigit(value.charAt(0))||value.matches("[+-][0-9].*");String before=numeric?"(?<![0-9.+-])":"",after=Character.isDigit(value.charAt(value.length()-1))?"(?![0-9.]|[eE][+-]?[0-9])":"";String pattern=java.util.Arrays.stream(value.split(" ")).map(java.util.regex.Pattern::quote).collect(java.util.stream.Collectors.joining("\\s*"));return java.util.regex.Pattern.compile(before+pattern+after).matcher(spaced(fragment)).find();}
 static String observationKey(Map<String,Object> item,String location){return ReportMatchingService.norm(item.get("original_field_name"))+":"+location+":"+spaced(item.get("unit_raw"))+":"+spaced(item.get("reference_range_raw"));}
 static boolean separateGenericObservation(Map<String,Object> item,Map<String,Object> evidence){String name=ReportMatchingService.norm(item.get("original_field_name"));return Arrays.asList("既往史","现病史","现症状","其他","其它").contains(name)&&evidence!=null&&paragraph(evidence.get("raw_fragment")).contains(paragraph(name))&&literalResult(evidence.get("raw_fragment"),str(item.get("result_raw")));}
 static boolean blankOptionalResult(String name,Map<String,Object> evidence,Map<String,String> pages){if(evidence==null||!paragraph(name).matches("矫正视力[左右]"))return false;String nativePage=pages.get(evidence.get("source_file_id")+":"+evidence.get("page_number"));if(nativePage==null)return false;for(String line:nativePage.split("[\\r\\n]+"))if(paragraph(line).equals(paragraph(name)))return true;return false;}
 boolean sourceCompleteConclusion(String report,int revision,Map<String,Map<String,Object>> evidence,Map<String,String> pages){for(Map<String,Object> c:db.all("SELECT original_field_name,original_text,primary_evidence_id FROM a_health_conclusions WHERE report_id=? AND revision=?",report,revision)){Map<String,Object> e=evidence.get(str(c.get("primary_evidence_id")));if(e==null)continue;String nativePage=pages.get(e.get("source_file_id")+":"+e.get("page_number")),body=paragraph(c.get("original_text"));if(nativePage!=null&&body.length()>=20&&paragraph(nativePage).contains(body)&&java.util.regex.Pattern.compile("总检\\s*(?:结论|意见)|体检\\s*总结|综合\\s*结论").matcher(nativePage).find()&&java.util.regex.Pattern.compile("总检\\s*(?:医生|医师|日期)").matcher(nativePage).find())return true;}return false;}

 boolean nativeVerified(Map<String,String> pages,Map<String,Object> e,Map<String,Object> item){String text=pages.get(e.get("source_file_id")+":"+e.get("page_number"));if(text==null)return false;String value=ReportMatchingService.norm(item.get("result_raw")),label=ReportMatchingService.norm(item.get("original_field_name"));if(label.isEmpty()||value.isEmpty()||!text.contains(label)||!literalResult(text,value))return false;for(String key:Arrays.asList("unit_raw","reference_range_raw")){String field=ReportMatchingService.norm(item.get(key));if(!field.isEmpty()&&!text.contains(field))return false;}return true;}
 public List<Map<String,Object>> medicalAlerts(String report,int revision){List<Map<String,Object>> alerts=new ArrayList<>();for(Map<String,Object> item:db.all("SELECT item_id,original_field_name,result_raw,unit_raw,abnormal_flag_raw FROM a_health_items WHERE report_id=? AND revision=?",report,revision)){String flag=str(item.get("abnormal_flag_raw"));if(Arrays.asList("HH","LL").contains(flag.toUpperCase(Locale.ROOT))||flag.contains("危急")){Map<String,Object> alert=issue("critical:"+item.get("item_id"),"medical","critical",str(item.get("item_id")),str(item.get("original_field_name"))+"：原报告标记疑似危急值，请医疗人员及时核对处理；系统未作诊断");alert.put("observationDigest",hex(digest(bytes(str(item.get("original_field_name"))+":"+str(item.get("result_raw"))+":"+str(item.get("unit_raw"))+":"+flag))));alerts.add(alert);}}return alerts;}

}
